package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;

/**
 * Unit tests for UniformRealDistribution#isSupportUpperBoundInclusive
 */
public class UniformRealDistribution_isSupportUpperBoundInclusive_TriageGen0Test {

    @Test
    public void testIsSupportUpperBoundInclusiveWithDefaultConstructor() {
        // Default constructor uses lower=0.0, upper=1.0
        UniformRealDistribution distribution = new UniformRealDistribution();
        assertFalse("The upper bound should not be inclusive for a standard UniformRealDistribution", 
            distribution.isSupportUpperBoundInclusive());
    }

    @Test
    public void testIsSupportUpperBoundInclusiveWithParameters() {
        // Testing with explicit parameters
        UniformRealDistribution distribution = new UniformRealDistribution(1.0, 10.0);
        assertFalse("The upper bound should not be inclusive", 
            distribution.isSupportUpperBoundInclusive());
    }

    @Test
    public void testIsSupportUpperBoundInclusiveWithAccuracy() {
        // Testing with accuracy parameter
        UniformRealDistribution distribution = new UniformRealDistribution(0.0, 1.0, 1e-10);
        assertFalse("The upper bound should not be inclusive", 
            distribution.isSupportUpperBoundInclusive());
    }

    @Test
    public void testIsSupportUpperBoundInclusiveWithRandomGenerator() {
        // Testing with RandomGenerator
        org.apache.commons.math3.random.JDKRandomGenerator rng = new org.apache.commons.math3.random.JDKRandomGenerator();
        UniformRealDistribution distribution = new UniformRealDistribution(rng, 0.0, 1.0, 1e-10);
        assertFalse("The upper bound should not be inclusive", 
            distribution.isSupportUpperBoundInclusive());
    }
}
